    "            Sphere s = sp.s[idx];\n"
    "            vec3 p = o + d * tmin, nr = (p - s.p.xyz) / s.p.w;\n"
    "            int type = int(s.c.w);\n"
    "            if ((u_dbg & 4) != 0) {\n"
    "                col = thr * s.c.rgb;\n"
    "                break;\n"
    "            }\n"
    "            if (type == 2) { // a mirror: on with the reflected ray\n"
    "                if (dot(nr, d) >= 0.0)\n"
    "                    break; // inside a sphere: dark\n"
    "                thr *= s.c.rgb;\n"
    "                d = reflect(d, nr);\n"
    "                o = p;\n"
    "                continue;\n"
    "            }\n"
    "            if (type == 1 && glint(p, nr, d, s.p)) {\n"
    "                col = thr;\n"
    "                break;\n"
    "            }\n"
    "            col = thr * pixbrite(p, nr, s.c.rgb, s.p);\n"
    "            break;\n"
    "        }\n"
    "        float s2 = d.z * d.z; // rt1.c's skybrite\n"
    "        col = thr * ((1.0 - s2) * u_hor + s2 * u_zen);\n"
    "        break;\n"
    "    }\n"
    "    if (u_levels != 0)\n"
    "        imageStore(u_lv, pix, vec4(clamp(floor(col * 16.0 + 0.5), 0.0, 15.0) / 15.0, 1.0));\n"
    "    else\n"
    "        imageStore(u_hdr, pix, vec4(mix(texelFetch(u_prev, pix, 0).rgb, col, u_blend), 1.0));\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    uint lid = gl_LocalInvocationIndex;\n"
    "\n"
    "    // the tile's cone: its axis, and the widest angle to a corner\n"
    "    vec2 c0 = vec2(gl_WorkGroupID.xy * uint(TILE * SUB)) - 1.0, c1 = c0 + float(TILE * SUB + 2);\n"
    "    vec3 axis = normalize(dir_at(0.5 * (c0 + c1)));\n"
    "    float co = min(min(dot(axis, normalize(dir_at(c0))), dot(axis, normalize(dir_at(c1)))),\n"
    "                   min(dot(axis, normalize(dir_at(vec2(c0.x, c1.y)))), dot(axis, normalize(dir_at(vec2(c1.x, c0.y))))));\n"
    "    float si = sqrt(max(1.0 - co * co, 0.0));\n"
    "    if (lid == 0u)\n"
    "        s_n = 0u;\n"
    "    barrier();\n"
    "    for (int i = int(lid); i < u_ns; i += TILE * TILE) {\n"
    "        vec4 s = sp.s[i].p;\n"
    "        vec3 v = s.xyz - u_eye;\n"
    "        float d = dot(v, axis), l2 = dot(v, v);\n"
    "        float perp = sqrt(max(l2 - d * d, 0.0));\n"
    "        if (l2 <= s.w * s.w || (d > -s.w && co * perp - si * d <= s.w)) {\n"
    "            uint k = atomicAdd(s_n, 1u);\n"
    "            if (k < uint(LIST))\n"
    "                s_list[k] = uint(i), s_sph[k] = s;\n"
    "        }\n"
    "    }\n"
    "    barrier();\n"
    "    uint n = s_n;\n"
    "    ivec2 base = ivec2(gl_WorkGroupID.xy) * (TILE * SUB) + ivec2(gl_LocalInvocationID.xy);\n"
    "    for (int sy = 0; sy < SUB; sy++)\n"
    "        for (int sx = 0; sx < SUB; sx++) {\n"
    "            ivec2 pix = base + ivec2(sx, sy) * TILE;\n"
    "            if (pix.x < u_size.x && pix.y < u_size.y)\n"
    "                trace(pix, n);\n"
    "        }\n"
    "}\n"
    ;

static const char ham_comp[] =
    "#version 310 es\n"
    "// The 1987 look: rt3.c's ham2 for each row of the 4-bit picture (one\n"
    "// invocation a row, left to right, as the Amiga's HAM6 display decodes it).\n"
    "// A pixel either takes the nearest of the 16 colour registers (made once\n"
    "// by rt3.c's allocation over the scene's first picture) or holds the\n"
    "// colour on its left and changes one channel, the one most wrong: the\n"
    "// fringes of HAM.\n"
    "//\n"
    "// The nearest register of each of the 4096 colours is looked up in u_near\n"
    "// (64 x 64, made on the CPU with the registers: rgb the register, a its\n"
    "// distance), not searched: a uniform array indexed in a loop is a memory\n"
    "// read a time on V3D. Sixteen rows a work group, one a lane.\n"
    "precision highp float;\n"
    "precision highp int;\n"
    "layout(local_size_x = 256) in;\n"
    "layout(rgba8, binding = 2) writeonly uniform highp image2D u_ham;\n"
    "uniform highp sampler2D u_lvtex;\n"
    "uniform highp sampler2D u_near;\n"
    "uniform ivec2 u_size;\n"
    "\n"
    "ivec3 level(int x, int y)\n"
    "{\n"
    "    return ivec3(texelFetch(u_lvtex, ivec2(x, y), 0).rgb * 15.0 + 0.5);\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    int y = int(gl_GlobalInvocationID.x);\n"
    "    if (y >= u_size.y)\n"
    "        return;\n"
    "    ivec3 prev = ivec3(0), next = level(0, y);\n"
    "    for (int x = 0; x < u_size.x; x++) {\n"
    "        ivec3 p = next;\n"
    "        next = level(min(x + 1, u_size.x - 1), y); // the next one on its way meanwhile\n"
    "        int i = p.r * 256 + p.g * 16 + p.b;\n"
    "        vec4 nr = texelFetch(u_near, ivec2(i & 63, i >> 6), 0);\n"
    "        ivec3 e = abs(p - prev);\n"
    "        int dif = e.r + e.g + e.b - max(e.r, max(e.g, e.b)); // rt3.c's coldist\n"
    "        if (x == 0 || (dif != 0 && int(nr.a * 255.0 + 0.5) < dif))\n"
    "            prev = ivec3(nr.rgb * 15.0 + 0.5);\n"
    "        else if (e.r >= e.g && e.r >= e.b && e.r > 0) // hold and modify the worst channel (the first of equals)\n"
    "            prev.r = p.r;\n"
    "        else if (e.g >= e.b && e.g > 0)\n"
    "            prev.g = p.g;\n"
    "        else\n"
    "            prev.b = p.b;\n"
    "        imageStore(u_ham, ivec2(x, y), vec4(vec3(prev) / 15.0, 1.0));\n"
    "    }\n"
    "}\n"
    ;

